def max_fill(grid, capacity):
    import math
    num_wells = len(grid)
    initial_state = ''.join([str(x) for row in grid for x in row])
    final_state = ''.join(['0' * len(row) for row in grid])
    queue = [(initial_state, 0)]
    visited = set(initial_state)
    while queue:
        state, steps = queue.pop(0)
        steps += 1
        for i in range(num_wells):
            if set(state[i * len(grid[0]):(i + 1) * len(grid[0])]) == {'0'}:
                continue
            for j in range(num_wells):
                if set(state[j * len(grid[0]):(j + 1) * len(grid[0])]) == {'1'}:
                    continue
                water_to_move = min(state[i * len(grid[0]):(i + 1) * len(grid[0])].count('1'), capacity - state[j * len(grid[0]):(j + 1) * len(grid[0])].count('1'))
                if water_to_move == 0:
                    continue
                new_state = list(state)
                new_state[i * len(grid[0]):(i + 1) * len(grid[0])] = ['0' for x in range(len(grid[0]))]
                new_state[j * len(grid[0]):(j + 1) * len(grid[0])] = ['1' for x in range(water_to_move)]
                new_state = ''.join(new_state)
                if new_state == final_state:
                    return steps
                if new_state not in visited:
                    visited.add(new_state)
                    queue.append((new_state, steps))
    return -1

